web_global_verification("Text/IC=text2", "Fail=NotFound", "ID=text_3_verify", LAST);

/* The check is performed for all of the verifications above. */
web_url("Search for 1_2_3", "URL=...", LAST);

web_global_verification_pause("ID=text_3_verify", "ID=text_1_verify", LAST);

/* Only text_2_verify is checked; the others are suspended. */
web_url("Search for 2 only", "URL=...", LAST);

web_global_verification_pause("ID=text_3_verify", "ID=text_1_verify", LAST);

/* Only text_2_verify is checked. */
web_url("Search for 2 only", "URL=...", LAST);

web_global_verification_resume("ID=text_3_verify", LAST);

/* text_2_verify and text_3_verify are checked; text_1_verify is still suspended. */
web_url("Search for 2 and 3", "URL=...", LAST);

